import {spawnSync} from 'node:child_process';
import {mkdirSync,writeFileSync} from 'node:fs';
const candidate='/private/tmp/intl-native-current-consumer-1uw94sgu';
const baseline='/private/tmp/intl-native-published-baseline-hnz9n6lh';
const out='/private/tmp/intl-native-execution-evidence/preparation-comparison-f71-published';
mkdirSync(out,{recursive:false});
const cells=[
 {label:'candidate-rust-full-preparation',root:candidate,engine:'rust',operation:'full-preparation'},
 {label:'published-node-full-preparation',root:baseline,engine:'node',operation:'full-preparation'},
 {label:'candidate-node-full-preparation',root:candidate,engine:'node',operation:'full-preparation'},
 {label:'candidate-rust-cli-reuse',root:candidate,engine:'rust',operation:'cli-reuse'},
 {label:'published-node-verify',root:baseline,engine:'node',operation:'verify'},
];
const commands=[];
for(let block=0;block<2;block++){
 for(const cell of block===0?cells:[...cells].reverse()){
  const label=cell.label+'-'+block;
  const args=['benchmarks/ci-operation.mjs','--label',label,'--mode','cold','--samples','5','--warmups','0','--timeout-ms','180000','--total-timeout-ms','1000000','--cwd',cell.root,'--input',cell.root+'/pnpm-lock.yaml','--input',cell.root+'/.intl-candidate/benchmark-preparation-operation.mjs','--output',out+'/'+label+'.json','--',process.execPath,'.intl-candidate/benchmark-preparation-operation.mjs',cell.operation,'cold'];
  commands.push({label,args,...cell,context:'Source42a898e5 identical; published0.3.29 versus exactfivecandidatepacks; two reverse-orderblocks; freshCLIprocesses with warmed OS cache, no CPU isolation; includes outputdigest and benchmarkoutputcleanup; excludes dependencyrestore/runnerstartup/transfers'});
  writeFileSync(out+'/commands.json',JSON.stringify(commands,null,2)+'\n');
  process.stdout.write('Start '+label+'\n');
  const r=spawnSync(process.execPath,args,{env:{...process.env,MIRAI_INTL_ENGINE:cell.engine},encoding:'utf8',timeout:1030000,maxBuffer:1048576});
  writeFileSync(out+'/'+label+'.log',(r.stdout??'')+(r.stderr??''));
  if(r.error||r.signal||r.status!==0)throw new Error(label+': '+(r.error??r.signal??r.status));
  process.stdout.write('Passed '+label+'\n');
 }
}

import {spawnSync} from 'node:child_process';
import {existsSync,readFileSync,writeFileSync} from 'node:fs';
const candidate='/private/tmp/intl-native-current-consumer-1uw94sgu';
const baseline='/private/tmp/intl-native-published-baseline-hnz9n6lh';
const out='/private/tmp/intl-native-execution-evidence/preparation-comparison-f71-published';
// Resume preserves every completed and failed original record.

const cells=[
 {label:'candidate-rust-full-preparation',root:candidate,engine:'rust',operation:'full-preparation'},
 {label:'published-node-full-preparation',root:baseline,engine:'node',operation:'full-preparation'},
 {label:'candidate-node-full-preparation',root:candidate,engine:'node',operation:'full-preparation'},
 {label:'candidate-rust-cli-reuse',root:candidate,engine:'rust',operation:'cli-reuse'},
 {label:'published-node-verify',root:baseline,engine:'node',operation:'verify'},
];
const commands=[];
for(let block=0;block<2;block++){
 for(const cell of block===0?cells:[...cells].reverse()){
  const original=cell.label+'-'+block;
  const existing=out+'/'+original+'.json';
  if(existsSync(existing)&&JSON.parse(readFileSync(existing,'utf8')).status==='success')continue;
  const label=original+(existsSync(existing)?'-retry':'');
  let args=['benchmarks/ci-operation.mjs','--label',label,'--mode','cold','--samples','5','--warmups','0','--timeout-ms','180000','--total-timeout-ms','1000000','--cwd',cell.root,'--input',cell.root+'/pnpm-lock.yaml','--input',cell.root+'/.intl-candidate/benchmark-preparation-operation.mjs','--output',out+'/'+label+'.json','--',process.execPath,'.intl-candidate/benchmark-preparation-operation.mjs',cell.operation,'cold'];
  if(cell.operation==='cli-reuse'){
   const boundary=args.indexOf('--');
   args=[...args.slice(0,boundary),'--input','/Users/kentakoong/Desktop/Work/openmirai/org/worktrees/fe-mirai-intl-native-adoption/.github/scripts/prepare-intl-authority.mjs','--input',candidate+'/.intl-candidate/benchmark-authority.tar','--input',process.cwd()+'/.tmp/benchmark-forwarding-cli.mjs','--',process.execPath,process.cwd()+'/.tmp/benchmark-forwarding-cli.mjs'];
  }
  commands.push({label,args,...cell,context:'Source42a898e5 identical; published0.3.29 versus exactfivecandidatepacks; two reverse-orderblocks; freshCLIprocesses with warmed OS cache, no CPU isolation; includes outputdigest and benchmarkoutputcleanup; excludes dependencyrestore/runnerstartup/transfers'});
  writeFileSync(out+'/commands-resume.json',JSON.stringify(commands,null,2)+'\n');
  process.stdout.write('Start '+label+'\n');
  const r=spawnSync(process.execPath,args,{env:{...process.env,MIRAI_INTL_ENGINE:cell.engine},encoding:'utf8',timeout:1030000,maxBuffer:1048576});
  writeFileSync(out+'/'+label+'.log',(r.stdout??'')+(r.stderr??''));
  if(r.error||r.signal||r.status!==0)throw new Error(label+': '+(r.error??r.signal??r.status));
  process.stdout.write('Passed '+label+'\n');
 }
}

import {spawnSync} from 'node:child_process';
import {mkdirSync,writeFileSync} from 'node:fs';
const root='/private/tmp/intl-native-current-consumer-1uw94sgu';
const out='/private/tmp/intl-native-execution-evidence/workspace-comparison-f71-all-targets';
mkdirSync(out,{recursive:true});
const commands=[];
for(let block=0;block<2;block++){
 for(const mode of ['cold','warm']){
  for(const operation of ['verify','reuse']){
   for(const engine of block===0?['node','rust']:['rust','node']){
    const label=`${operation}-${mode}-${engine}-${block}`;
    const args=['benchmarks/ci-operation.mjs','--label',label,'--mode',mode,'--samples','5','--warmups',mode==='warm'?'1':'0','--timeout-ms','120000','--total-timeout-ms','900000','--cwd',root,'--input',`${root}/pnpm-lock.yaml`,'--input',`${root}/.intl-candidate/benchmark-authority.tar`,'--input',`${root}/.intl-candidate/benchmark-workspace-operation.mjs`,'--output',`${out}/${label}.json`,'--',process.execPath,'.intl-candidate/benchmark-workspace-operation.mjs',operation,mode];
    commands.push({label,args,engine,context:'same all-target candidate package, current Turbo staging inputs; sequential blocks; fresh processes versus persistent operation worker, never cleared OS cache'});
    writeFileSync(`${out}/commands.json`,JSON.stringify(commands,null,2)+'\n');
    process.stdout.write(`Start ${label}\n`);
    const r=spawnSync(process.execPath,args,{env:{...process.env,MIRAI_INTL_ENGINE:engine},encoding:'utf8',timeout:930000,maxBuffer:1048576});
    writeFileSync(`${out}/${label}.log`,`${r.stdout??''}${r.stderr??''}`);
    if(r.error||r.signal||r.status!==0)throw new Error(`${label}: ${r.error??r.signal??r.status}`);
    process.stdout.write(`Passed ${label}\n`);
   }
  }
 }
}

import {spawnSync} from 'node:child_process';
import assert from 'node:assert/strict';
import {resolve} from 'node:path';
import {stat,unlink} from 'node:fs/promises';
const helper='/Users/kentakoong/Desktop/Work/openmirai/org/worktrees/fe-mirai-intl-native-adoption/.github/scripts/prepare-intl-authority.mjs';
const candidate=resolve('.intl-candidate/benchmark-authority.tar');
const output=resolve('.intl-candidate/benchmark-cli-forwarded-'+process.pid+'.tar');
const r=spawnSync(process.execPath,[helper,'--candidate',candidate,'--output',output],{encoding:'utf8',timeout:180000,maxBuffer:16*1024*1024});
if(r.error||r.signal||r.status!==0)throw new Error((r.error??r.signal??r.status)+'\n'+r.stderr+'\n'+r.stdout);
assert.equal(JSON.parse(r.stdout).reuseStatus,'reused');
process.stdout.write(JSON.stringify({reuseStatus:'reused',bytes:(await stat(output)).size})+'\n');
await unlink(output);

import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {readFile,realpath} from 'node:fs/promises';
import {createInterface} from 'node:readline';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {createRequire} from 'node:module';
const [operation, lifecycle = 'cold'] = process.argv.slice(2);
const root=process.cwd();
const cli=resolve('apps/admin/node_modules/@openmirai/intl/dist/cli.js');
const api=await import(pathToFileURL(createRequire(await realpath(cli)).resolve('@openmirai/intl-compiler/verify')).href);
const candidate=resolve('.intl-candidate/benchmark-authority.tar');
const output=resolve('.intl-candidate/benchmark-produced-authority.tar');
const digest=async path=>createHash('sha256').update(await readFile(path)).digest('hex');
function checked(command,args) {
 const r=spawnSync(command,args,{cwd:root,env:process.env,encoding:'utf8',timeout:300000,maxBuffer:16*1024*1024});
 if(r.error||r.signal||r.status!==0)throw new Error(`Operation failed ${command} ${args.join(' ')}: ${r.error??r.signal??r.status}\n${r.stderr}\n${r.stdout}`);
 return r.stdout;
}
function counters(results){assert.equal(results.length,5);for(const r of results){assert.equal(r.catalogCompilations,0);assert.equal(r.artifactEmissions,0);assert.equal(r.buildSemanticAnalysisRuns,0);assert.equal(r.verifiedCatalogs,1)}}
async function run(){
 if(operation==='verify'){counters(await api.verifyWorkspaceBuildReceipts(root));return;}
 if(operation==='reuse'){
  const result=await api.reuseAuthorityBundle({root,archive:candidate});
  assert.equal(result.status,'reused',JSON.stringify(result));
  counters(await api.verifyWorkspaceBuildReceipts(root));
  return;
 }
 if(operation==='full-preparation'){
  const report=JSON.parse(checked(process.execPath,[cli,'check','--workspace','--format=json']));
  assert.equal(report.success,true);assert.equal(report.summary.catalogCount,5);
  checked('bash',['.github/scripts/intl-authority.sh','export',output]);
  return;
 }
 throw new Error('Unknown benchmark operation');
}
if(lifecycle==='warm'){
 assert.notEqual(operation,'full-preparation','CLI preparation has no persistent semantic operation API');
 process.stdout.write('{"type":"ready","protocol":"ci-operation-v1"}\n');
 for await(const line of createInterface({input:process.stdin,crlfDelay:Infinity})){
  const request=JSON.parse(line);if(request.type==='shutdown')break;
  assert.equal(request.type,'run');await run();process.stdout.write(JSON.stringify({type:'result',id:request.id,ok:true})+'\n');
 }
}else{await run();process.stdout.write(JSON.stringify({operation,ok:true,candidateDigest:operation==='reuse'?await digest(candidate):null})+'\n')}

