import {createRequire,syncBuiltinESMExports} from 'node:module';
import {pathToFileURL} from 'node:url';
import {threadId} from 'node:worker_threads';
import {performance} from 'node:perf_hooks';
import {mock} from 'node:test';
const req=createRequire(import.meta.url);
const fs=req('node:fs'), fsp=req('node:fs/promises'), crypto=req('node:crypto');
const started=performance.now(),startedCpu=process.cpuUsage();
const readPaths=new Map();
const countPath=(path,n)=>{const key=String(path);const current=readPaths.get(key)??{count:0,bytes:0};current.count++;current.bytes+=n;readPaths.set(key,current)};
const originalWrite=fs.writeFileSync.bind(fs);
const root=process.env.INTL_PROFILE_ROOT, output=process.env.INTL_PROFILE_OUTPUT;
if(!root||!output)throw new Error('Explicit profile root/output required');
const result={pid:process.pid,parent:process.ppid,threadId,cwd:process.cwd(),node:process.version,reads:{sync:0,async:0,bytes:0},hash:{constructors:0,updates:0,inputBytes:0},directory:{sync:0,async:0},programs:[],sourceFileCalls:0};
const bytes=(data,encoding)=>typeof data==='string'?Buffer.byteLength(data,encoding):data?.byteLength??0;
const originalReadSync=fs.readFileSync.bind(fs);
fs.readFileSync=(...args)=>{const value=originalReadSync(...args);result.reads.sync++;result.reads.bytes+=bytes(value);countPath(args[0],bytes(value));return value};
const originalRead=fsp.readFile.bind(fsp);
fsp.readFile=async(...args)=>{const value=await originalRead(...args);result.reads.async++;result.reads.bytes+=bytes(value);countPath(args[0],bytes(value));return value};
const originalDirSync=fs.readdirSync.bind(fs);
fs.readdirSync=(...args)=>{result.directory.sync++;return originalDirSync(...args)};
const originalDir=fsp.readdir.bind(fsp);
fsp.readdir=async(...args)=>{result.directory.async++;return originalDir(...args)};
const originalHash=crypto.createHash.bind(crypto);
crypto.createHash=(...args)=>{
 result.hash.constructors++;const hash=originalHash(...args),update=hash.update.bind(hash);
 hash.update=(data,encoding)=>{result.hash.updates++;result.hash.inputBytes+=bytes(data,encoding);return update(data,encoding)};
 return hash;
};
syncBuiltinESMExports();
const intl=createRequire(root+'/apps/admin/package.json').resolve('@openmirai/intl');
const compiler=createRequire(intl).resolve('@openmirai/intl-compiler');
const tsPath=createRequire(compiler).resolve('typescript');
const original=await import(pathToFileURL(tsPath).href);
const ts=original.default??original;
const wrapped={...ts};
result.typescript={path:tsPath,version:ts.version};
for(const name of ['createProgram','createIncrementalProgram','createSemanticDiagnosticsBuilderProgram']){
 if(typeof ts[name]!=='function')continue;
 wrapped[name]=(...args)=>{
  const start=performance.now(),cpu=process.cpuUsage();
  const input=Array.isArray(args[0])?args[0]:args[0]?.rootNames;
  const options=Array.isArray(args[0])?args[1]:args[0]?.options;
  let program;
  try{program=ts[name](...args);return program}
  finally{
   if(result.programs.length>=100)throw new Error('Unexpected program count exceeds profile bound');
   result.programs.push({api:name,roots:input??null,config:options?.configFilePath??null,elapsedMs:performance.now()-start,cpu:process.cpuUsage(cpu),sourceFiles:(program?.getSourceFiles?.()??program?.getProgram?.()?.getSourceFiles?.()??[]).map(file=>file.fileName)});
  }
 };
}
wrapped.createSourceFile=(...args)=>{result.sourceFileCalls++;return ts.createSourceFile(...args)};
mock.module(tsPath,{defaultExport:wrapped,namedExports:wrapped});
process.on('exit',()=>{result.elapsedMs=performance.now()-started;result.cpu=process.cpuUsage(startedCpu);result.resourceUsage=process.resourceUsage();result.readPaths=Object.fromEntries(readPaths);originalWrite(output+'/'+process.pid+'-'+threadId+'.json',JSON.stringify(result))});
